package com.mongodb.saas.billing.controller;

import com.mongodb.saas.billing.document.BilledInvoiceDoc;
import com.mongodb.saas.billing.security.TenantUserPrincipal;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/mongo/billing/invoices")
public class MongoInvoiceController {

    private final MongoTemplate mongoTemplate;

    public MongoInvoiceController(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    @GetMapping("/{invoiceCode}")
    public ResponseEntity<BilledInvoiceDoc> getInvoiceByCode(
            @PathVariable String invoiceCode,
            @AuthenticationPrincipal TenantUserPrincipal principal) {
        Query query = new Query(new Criteria().andOperator(
                Criteria.where("invoiceCode").is(invoiceCode),
                Criteria.where("tenantId").is(principal.getTenantId())
        ));
        BilledInvoiceDoc invoice = mongoTemplate.findOne(query, BilledInvoiceDoc.class);
        if (invoice == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(invoice);
    }
}
